import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"關於","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/about.md","filePath":"zh-TW/user-guide/settings/about.md","lastUpdated":1786082398000}'),s={name:"zh-TW/user-guide/settings/about.md"};function n(i,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="關於" tabindex="-1">關於 <a class="header-anchor" href="#關於" aria-label="Permalink to &quot;關於&quot;">​</a></h1><p>顯示 App、Core、Service、CLI 四個元件的版本號(顏色會反映服務目前是否健康)、Lertaro 的簡短說明，以及專案首頁和線上使用手冊的連結。</p><h2 id="資料目錄" tabindex="-1">資料目錄 <a class="header-anchor" href="#資料目錄" aria-label="Permalink to &quot;資料目錄&quot;">​</a></h2><p>緊接著下方還有兩個連結，用來開啟 Lertaro 讀寫自身設定的資料夾——連結文字本身就是實際路徑，點擊時如果資料夾還不存在會先建立出來:</p><ul><li><strong>使用者資料目錄</strong> —— 存放 <code>user-settings.json</code> 的每使用者目錄。每次儲存設定時，都會先把目前檔案輪替備份為 <code>user-settings.json.bak.1</code>(舊的備份依次往後順延，最多保留到 <code>.bak.5</code>)，再寫入新檔案，所以一次誤改或者儲存過程中當機，總能找到一份最近的備份還原。搜尋記錄、憑證和使用者專屬快取也保存在這裡。</li><li><strong>機器資料目錄</strong> —— 背景服務使用的機器層級目錄(<code>machine-settings.json</code>、本機磁碟索引快取，以及服務端記錄)。</li></ul><p>安裝版使用 <code>%LocalAppData%\\Lertaro</code> 和 <code>%ProgramData%\\Lertaro</code>。可攜版在程式旁使用 <code>Data\\Users\\&lt;SID hash&gt;</code> 和 <code>Data\\Machine</code>;如果可攜版的 <code>Data</code> 目錄尚未建立，為了相容會重複使用已有的安裝版資料。目錄優先順序請參閱<a href="./../getting-started.html#可攜版資料">可攜版資料</a>。</p><h2 id="檢查更新" tabindex="-1">檢查更新 <a class="header-anchor" href="#檢查更新" aria-label="Permalink to &quot;檢查更新&quot;">​</a></h2><ul><li><strong>檢查更新</strong> 按鈕 —— 查詢是否有新版本;按鈕文字本身會反映進度(「正在檢查更新...」，之後顯示「已是最新版本」或找到的新版本號)。</li><li>如果非系統管理員帳戶無法停止背景服務來原地安裝更新，會顯示一條警告橫幅，並引導你前往手動下載頁面。</li><li>一旦發現新版本: <ul><li><strong>靜默自動更新</strong> —— 背景下載安裝，顯示進度條，完成後自動重新啟動 Lertaro。</li><li><strong>前往下載頁面</strong> —— 在瀏覽器中開啟 GitHub release 頁面，手動安裝。</li></ul></li></ul><p>這個頁面和<a href="./general.html#系統">通用 → 系統</a>裡的<strong>啟動時自動檢查更新</strong> / <strong>自動靜默更新</strong>兩個核取方塊是配套的——那兩項控制是否在啟動時自動執行這次檢查;這個頁面則是讓你隨時手動觸發一次。</p>',9)])])}const p=t(s,[["render",n]]);export{h as __pageData,p as default};
